/// Prepares immutable read-only authority for an ACP Ask startup without
/// starting provider processes on the caller thread.
pub(crate) fn prepare_ask_session_request(
    &self,
    host: &AgentHost,
    gameengine_session_id: &str,
) -> Result<AcpSessionOpenRequest, AcpBridgeError> {
    host.session(gameengine_session_id)?;
    let binding = AcpSessionBinding::read_only(
        gameengine_session_id,
        self.mcp.endpoint.clone(),
        self.mcp.read_only_token.clone(),
    )?;
    Ok(AcpSessionOpenRequest::new(
        binding,
        self.working_directory.clone(),
    )?)
}

/// Prepares immutable run-bound authority before a Build startup worker is
/// launched. Agent Host is checked again when the opened session returns.
pub(crate) fn prepare_run_session_request(
    &self,
    host: &AgentHost,
    gameengine_session_id: &str,
    run_id: &str,
    working_directory: PathBuf,
) -> Result<AcpSessionOpenRequest, AcpBridgeError> {
    if !host
        .session(gameengine_session_id)?
        .runs
        .iter()
        .any(|run| run.id == run_id)
    {
        return Err(AcpBridgeError::RunSessionMismatch(run_id.to_owned()));
    }
    if host.run(run_id)?.state.is_terminal() {
        return Err(AcpBridgeError::TerminalRun(run_id.to_owned()));
    }
    let binding = AcpSessionBinding::run_bound(
        gameengine_session_id,
        run_id,
        self.mcp.endpoint.clone(),
        self.mcp.run_bound_token.clone(),
    )?;
    Ok(AcpSessionOpenRequest::new(binding, working_directory)?)
}

/// Attaches a worker-opened Ask session only if its immutable binding still
/// belongs to the same GameEngine session.
pub(crate) fn attach_ask_session(
    &mut self,
    host: &AgentHost,
    descriptor_id: String,
    session: Box<dyn AcpAgentSession>,
    gameengine_session_id: &str,
) -> Result<String, AcpBridgeError> {
    host.session(gameengine_session_id)?;
    self.attach_opened_session(
        descriptor_id,
        session,
        gameengine_session_id.to_owned(),
        None,
    )
}

/// Attaches a worker-opened Build session only while the authoritative run
/// is still non-terminal and still belongs to the same GameEngine session.
pub(crate) fn attach_run_session(
    &mut self,
    host: &mut AgentHost,
    descriptor_id: String,
    session: Box<dyn AcpAgentSession>,
    gameengine_session_id: &str,
    run_id: &str,
) -> Result<String, AcpBridgeError> {
    if !host
        .session(gameengine_session_id)?
        .runs
        .iter()
        .any(|run| run.id == run_id)
    {
        return Err(AcpBridgeError::RunSessionMismatch(run_id.to_owned()));
    }
    if host.run(run_id)?.state.is_terminal() {
        return Err(AcpBridgeError::TerminalRun(run_id.to_owned()));
    }
    let acp_id = self.attach_opened_session(
        descriptor_id,
        session,
        gameengine_session_id.to_owned(),
        Some(run_id.to_owned()),
    )?;
    if let Err(error) = self.record_identity(host, &acp_id) {
        let _ = self.close_session(&acp_id);
        return Err(error);
    }
    Ok(acp_id)
}

fn attach_opened_session(
    &mut self,
    descriptor_id: String,
    mut session: Box<dyn AcpAgentSession>,
    expected_session_id: String,
    expected_run_id: Option<String>,
) -> Result<String, AcpBridgeError> {
    let identity = session.runtime_identity().clone();
    let acp_id = session.acp_session_id().to_owned();
    if acp_id.trim().is_empty() {
        let _ = session.close();
        return Err(AcpBridgeError::InvalidSessionId);
    }
    if self.sessions.contains_key(&acp_id) {
        let _ = session.close();
        return Err(AcpBridgeError::DuplicateSession(acp_id));
    }
    if session.binding().gameengine_session_id != expected_session_id {
        let _ = session.close();
        return Err(AcpBridgeError::BindingMismatch(
            "GameEngine session identity changed while opening ACP".to_owned(),
        ));
    }
    if session.binding().gameengine_run_id != expected_run_id {
        let _ = session.close();
        return Err(AcpBridgeError::BindingMismatch(
            "AgentRun identity changed while opening ACP".to_owned(),
        ));
    }
    self.sessions.insert(
        acp_id.clone(),
        AttachedSession {
            descriptor_id,
            identity,
            run_id: expected_run_id,
            session,
            pending_permissions: BTreeMap::new(),
            turn_finished: false,
        },
    );
    Ok(acp_id)
}

